import math

def parse_amount(text):
    if not text or not text.strip():
        raise ValueError("empty input")
    s = text.strip().replace(',', '.')
    if not s:
        raise ValueError("empty input")
    try:
        x = float(s)
    except ValueError:
        raise ValueError("non-finite value")
    if math.isnan(x) or math.isinf(x):
        raise ValueError("non-finite value")
    if x < 0:
        raise ValueError("negative value")
    return x
